var e={"bb-bench":{cues:[`Press your feet into the floor`,`Keep your wrists straight over your forearms`,`Touch the middle of your chest`,`Press the bar straight up`],mistakes:[`The bar drifts toward your neck or belly`,`Your elbows flare straight out to the sides`,`Your wrists bend backward`,`Your hips lift off the bench while pressing`],breathing:`Breathe in as you lower the bar to your chest, and breathe out as you press it back up.`},"machine-chest":{cues:[`Keep your feet flat on the floor`,`Do not hyperextend your elbows`,`Press evenly with both arms`,`Squeeze your chest at the top`],mistakes:[`Your shoulders roll forward`,`Your lower back lifts off the bench`,`Using too much weight`,`Your wrists bend`],breathing:`Breathe out as you press up and in as you lower.`},"cable-fly":{cues:[`Lead the movement with your elbows`,`Keep your elbows slightly bent`,`Chest up`,`Do not let your shoulders roll forward`],mistakes:[`Taking your arms too far back`,`Locking out your elbows`,`Rounding your back`],breathing:`Breathe out as you bring your hands together, and in as you return.`},"dips-chest":{cues:[`Lean your torso forward`,`Keep your elbows pointing out to the sides`,`Lower under control`,`Do not lock out your elbows at the top`],mistakes:[`Staying too upright (shifts the load to the triceps)`,`Sinking too deep`,`Flaring your elbows out excessively`],breathing:`Breathe in as you lower and out as you press up.`},"db-ohp":{cues:[`No arching of the lower back`,`Brace your core`,`Keep your elbows under your wrists`,`Smooth transition`],mistakes:[`Leaning to the side`,`Pressing both dumbbells at the exact same time`,`Shrugging your shoulders`],breathing:`Breathe out as you press up and in as you lower.`},"arnold-press":{cues:[`Press and rotate in one fluid motion`,`Keep your ribs down`,`Wrists over your elbows`,`At the top your upper arms are next to your ears`],mistakes:[`Arching your lower back as the dumbbells go up`,`Flaring your elbows out to the sides at the bottom`,`Pressing the dumbbells up without rotating your hands`,`Lowering the dumbbells too fast and losing control`],breathing:`Breathe in at the bottom, out as you press and rotate, and in again as you lower.`},"machine-lateral":{cues:[`Lead with your elbows`,`Keep your shoulders down`,`Raise up to shoulder height`,`Lower under control`],mistakes:[`Shrugging your shoulders toward your ears`,`Swinging or bouncing the weight at the bottom`,`Raising your arms far above shoulder height`,`Your back comes off the pad`],breathing:`Breathe out as you raise your arms to the sides, and in as you lower them.`},"upright-row":{cues:[`Lead with your elbows`,`Keep the cable close to your body`,`Stop above your chest`,`Keep a neutral spine`],mistakes:[`Shrugging your shoulders excessively`,`Using too much momentum`,`Grip too narrow`],breathing:`Breathe out as you pull up and in as you lower.`},"db-rear-delt":{cues:[`Lead with your elbows`,`Keep your chest on the pad`,`Raise up to shoulder height`,`Lower under control`],mistakes:[`Throwing the dumbbells up with momentum`,`Shrugging your shoulders toward your ears`,`Straightening your elbows so it turns into a wide row`,`Raising your arms far above shoulder height`],breathing:`Breathe in as you lower the dumbbells and out as you raise them to the sides.`},chinup:{cues:[`Pull your shoulder blades together`,`Drive your elbows down`,`Brace your core`,`Do not swing`],mistakes:[`Using momentum`,`Flaring your elbows out`,`Incomplete range of motion`],breathing:`Breathe out as you pull up and in as you lower.`},"single-arm-pulldown":{cues:[`Pull your elbow down and toward your body`,`Do not shrug your shoulders`,`Keep your torso upright`,`Feel your lats working`],mistakes:[`Overarching your back`,`Letting your shoulder roll forward`,`Using momentum`],breathing:`Breathe out as you pull down and in as you return.`},"high-row-machine":{cues:[`Keep your chest against the pad`,`Pull your elbows back`,`Squeeze your shoulder blades together`,`Control the return`],mistakes:[`Shrugging your shoulders toward your ears while pulling`,`Lifting your chest off the pad to move the weight`,`Letting the handles snap forward between reps`,`Bending your wrists back instead of keeping them neutral`],breathing:`Breathe out as you pull the handles toward you, and in as you return to the start position.`},"single-arm-cable-row":{cues:[`Rotate your torso with the row`,`Chest up`,`Do not pull with a jerk`,`Control the return`],mistakes:[`Rotating too much`,`Using momentum`,`Shrugging your shoulder`],breathing:`Breathe out as you row and rotate, and in as you extend and return.`},"straight-arm-pulldown":{cues:[`Long arms, relaxed elbows`,`Pull with your lats`,`Ribs down, core braced`,`Stop at your thighs`],mistakes:[`Bending your elbows so it turns into a triceps pushdown`,`Leaning back and moving the bar with body momentum`,`Shrugging your shoulders toward your ears`,`Letting the bar drift away from your body at the bottom`],breathing:`Breathe in as the bar goes back up to the start, and out as you pull it to your thighs.`},"machine-shrug":{cues:[`Shrug your shoulders straight up`,`Keep your arms long`,`Keep your chest upright`,`Lower under control`],mistakes:[`Bending your elbows so it turns into a row`,`Rolling your shoulders forward or back`,`Leaning your torso to move the weight`,`Pushing your chin forward as your shoulders rise`],breathing:`Breathe in at the bottom, out as you shrug up, and in again as you lower.`},"reverse-hyper":{cues:[`Lift with your glutes`,`Keep your hips on the pad`,`Control the swing`,`Stop at torso height`],mistakes:[`Throwing your legs up with momentum`,`Arching your lower back at the top`,`Letting your hips slide off the pad`,`Bending and straightening your knees on every rep`],breathing:`Breathe in as you lower your legs and out as you raise them backward.`},"incline-db-curl":{cues:[`Keep your elbows still`,`Palms face forward`,`Lift with your biceps`,`Lower under control`],mistakes:[`Swinging the dumbbells to start the curl`,`Letting your elbows drift forward as you lift`,`Not lowering fully`,`Bending your wrists back while curling`],breathing:`Breathe in as you lower the dumbbells and out as you curl.`},"ez-curl":{cues:[`Keep your elbows still`,`Use the full range of motion`,`Do not swing the bar`,`Control the tempo`],mistakes:[`Using momentum`,`Letting your elbows drift forward`,`Incomplete reps`],breathing:`Breathe out as you curl up and in as you lower the bar.`},"rope-pushdown":{cues:[`Keep your elbows fixed`,`Pull the rope apart at the bottom`,`Do not use your shoulders`,`Fully extend on every rep`],mistakes:[`Flaring your elbows out`,`Using momentum`,`Not fully extending your arms`],breathing:`Breathe out as you push down and in as you return.`},skullcrusher:{cues:[`Keep your upper arms fixed`,`Lower under control`,`Do not move your elbows`,`Fully extend your triceps`],mistakes:[`Flaring your elbows out`,`Moving your upper arms`,`Lowering the bar too far behind your head`],breathing:`Breathe in as you lower the bar and out as you extend your arms.`},"close-grip-bench":{cues:[`Keep your elbows close to your body`,`Grip just inside shoulder width`,`Press with your triceps`,`Control the lowering`],mistakes:[`Grip too narrow or too wide`,`Flaring your elbows out`,`Bouncing the bar off your chest`],breathing:`Breathe out as you press up and in as you lower the bar.`},"db-kickback":{cues:[`Keep your elbow fixed at your side`,`Move only your forearm`,`Squeeze at full extension`,`Keep your back straight`],mistakes:[`Swinging the dumbbells with your shoulders or torso`,`Letting your elbows drift away from your ribs`,`Letting your upper arms drop during the set`,`Letting the weights drop instead of lowering them slowly`],breathing:`Breathe in as you bend your elbows back to the start, and out as you extend your arms backward.`},"reverse-wrist-curl":{cues:[`Keep your forearms still`,`Move slowly and under control`,`Move only your wrists`,`Do not swing`],mistakes:[`Using too much weight`,`Helping with your elbows or shoulders`,`Letting the barbell roll in your hands`],breathing:`Breathe out as you curl the bar up and in as you lower.`},"hack-squat":{cues:[`Keep your back against the pad`,`Knees track over your toes`,`Press through your whole foot`,`Control the lowering`],mistakes:[`Placing your feet too low so your heels lift`,`Letting your knees fall inward as you lower`,`Rounding your lower back or lifting your hips off the pad`,`Bouncing at the bottom instead of pausing briefly`],breathing:`Breathe in as you lower the sled and out as you press up.`},"goblet-squat":{cues:[`Chest up`,`Keep your heels on the floor`,`Knees track over your toes`,`Keep the dumbbell close to your body`],mistakes:[`Letting the dumbbell drift away from your chest`,`Lifting your heels off the floor at the bottom`,`Letting your knees fall inward as you bend`,`Folding your torso forward instead of staying upright`],breathing:`Breathe in as you lower into the squat and out as you stand up.`},rdl:{cues:[`Hips back, not down`,`Keep the bar close to your body`,`Soft knees, straight back`,`Stand tall at the top and squeeze your glutes`],mistakes:[`Bending your knees like in a squat as the bar lowers`,`Letting the bar drift forward away from your legs`,`Rounding your lower back at the bottom`,`Yanking the bar from the lowest point instead of lifting it smoothly`],breathing:`Breathe in and brace your core before you hinge forward, and breathe out as you stand up with your hip extension.`},"seated-leg-curl":{cues:[`Keep your hips pressed firmly into the seat`,`Curl through your heels`,`Move only at the knee joint`,`Lower under control`],mistakes:[`Lifting your hips off the seat while curling`,`Using momentum and swinging the pad through`,`Fully locking out your knees at the top`,`Setting the pad too high on your calves instead of above your ankles`],breathing:`Breathe out as you pull the pad down and in as you return to the start position.`},"hip-adduction":{cues:[`Sit upright`,`Control both directions`,`Squeeze your inner thighs`,`Keep your hips still`],mistakes:[`Leaning forward or lifting your lower back off the pad`,`Letting the pads fly open on the way back`,`Short, bouncy reps instead of a controlled motion`,`Excessively turning your feet and knees to force the movement`],breathing:`Breathe out as you squeeze your legs together, and in as you return to the start position.`},"seated-calf":{cues:[`Press through your big toe`,`Raise your heels straight up`,`Control the lowering`,`Keep your knees still`],mistakes:[`Bouncing at the bottom instead of lowering under control`,`Moving your knees up and down during the rep`,`Tipping your feet outward or inward on the plate`,`Using only the top half of the range of motion`],breathing:`Breathe in as you lower your heels and out as you press up onto the balls of your feet.`},"donkey-calf":{cues:[`Raise your heels straight up`,`Use the full range of motion`,`Press through your big toe`,`Lower under control`],mistakes:[`Bouncing at the bottom instead of lowering under control`,`Tipping your ankles inward or outward`,`Pushing your body up with your hands`,`Shortening the range and not lowering your heels deep enough`],breathing:`Breathe in as you lower your heels and out as you press up onto the balls of your feet.`},"machine-crunch":{cues:[`Move with your abs, not your hips`,`Do not use momentum`,`Controlled movement`,`Full range of motion`],mistakes:[`Letting your hip flexors take over`,`Using too much weight`,`Rushing the reps`,`Incomplete range of motion`],breathing:`Breathe out as you curl in and in as you return up.`},"cable-woodchop":{cues:[`Rotate from your ribcage`,`Keep your hips still`,`Move along the diagonal`,`Brace your core before rotating`],mistakes:[`Turning your hips and feet with the cable`,`Bending and straightening your elbows to move the weight`,`Letting the cable pull your torso back`,`Shrugging your shoulders toward your ears`],breathing:`Breathe out as you rotate and pull the handle across your body, and in as you return under control.`},"c-bike":{cues:[`Keep your back straight`,`Use the whole pedal stroke`,`Relax your shoulders`,`Keep breathing steadily`],mistakes:[`Slumping forward`,`Bouncing in the saddle`,`Pedaling only with your toes`,`Setting the saddle too low or too high`],breathing:`Breathe steadily and deeply throughout the workout.`},"decline-dumbbell-bench-press-45-degree":{cues:[`Control the lowering`,`Do not flare your elbows`,`Keep your wrists straight`,`Press through your heels`],mistakes:[`Letting your elbows sink too low`,`Uneven range of motion`,`Arching your lower back`,`Rushed reps`],breathing:`Breathe in as you lower the dumbbells and out as you press up.`,steps:[`Set the bench to a 45-degree decline.`,`Secure your feet and lie back with the dumbbells over your chest.`,`Lower the dumbbells to the sides of your chest.`,`Pause briefly at the bottom.`,`Press the weights back to the start position.`]},"dumbbell-lying-hammer-press":{cues:[`Palms face each other`,`Elbows slightly tucked`,`Press over the middle of your chest`,`Keep your wrists straight`],mistakes:[`Your elbows flare straight out to the sides.`,`The dumbbells drift toward your face instead of staying over your chest.`,`Your wrists bend back under the dumbbells.`,`Lowering too fast and bouncing at the bottom.`],breathing:`Breathe in as you lower the dumbbells to your chest and out as you press up.`,steps:[`Lie flat on the bench and press the dumbbells over your chest with your palms facing each other.`,`Plant your feet firmly on the floor and brace your core.`,`Lower the dumbbells under control to the sides of your chest, elbows slightly tucked.`,`Press the dumbbells straight up until your arms are extended.`,`Bring the dumbbells together over your chest and repeat.`]},"incline-push-ups":{cues:[`Keep your body in a straight line`,`Brace your core`,`Lower under control`,`Breathe out as you press up`],mistakes:[`Sagging hips`,`Flaring your elbows out`,`Incomplete range of motion`],breathing:`Breathe in as you lower and out as you press up.`,steps:[`Place your hands shoulder-width apart on an elevated surface.`,`Extend your legs back, feet together, body in a line.`,`Lower your chest toward the surface with your elbows at a 45° angle.`,`Push yourself back to the start position.`]},"dumbbell-one-arm-lateral-raise":{cues:[`Lead with your elbow`,`Stop at shoulder height`,`Keep your shoulders level`,`Lower under control`],mistakes:[`Shrugging the working shoulder toward your ear`,`Swinging your torso or leaning to lift`,`Lifting the dumbbell above shoulder height`,`Fully locking out your elbow`],breathing:`Breathe in as you lower the dumbbell and out as you raise it to the side.`,steps:[`Stand hip-width apart holding a dumbbell at your side, elbow slightly bent.`,`Brace your core; your free arm hangs loosely or rests on your hip.`,`Raise the dumbbell out to the side to about shoulder height.`,`Lower it again under control.`,`Do all reps on one side, then switch.`]},"barbell-front-raise":{cues:[`Raise up to shoulder height`,`Keep your ribs down`,`Lead with your hands`,`Do not swing`],mistakes:[`Leaning back to start the lift.`,`Swinging the barbell with your hips.`,`Raising the barbell above shoulder height.`,`Shrugging your shoulders toward your ears.`],breathing:`Breathe out as you raise the barbell and in as you lower it.`,steps:[`Stand hip-width apart holding the barbell in an overhand grip at your thighs.`,`Brace your core and keep your elbows slightly bent.`,`Raise the bar straight forward to shoulder height.`,`Lower it under control back to your thighs.`]},"dumbbell-rear-delt-row":{cues:[`Lead with your elbows.`,`Keep your back straight.`,`Raise your arms out to the sides, not backward.`,`Squeeze your shoulder blades together.`],mistakes:[`Rounding your lower back as you hinge forward.`,`Shrugging your shoulders toward your ears.`,`Pulling the dumbbells straight back close to your ribs.`,`Swinging your torso on every rep.`],breathing:`Breathe in as you lower the dumbbells and out as you row them up and out.`,steps:[`Stand hip- to shoulder-width apart with a dumbbell in each hand.`,`Hinge forward at the hips, knees soft, dumbbells hanging below your shoulders.`,`With a straight back, raise your elbows up and out to the sides.`,`Squeeze your upper back at the top and lower the dumbbells under control.`]},"cable-seated-high-row-v-bar":{cues:[`Chest up`,`Lead with your elbows`,`Squeeze your shoulder blades together`,`Control the return`],mistakes:[`Rounding your lower back when the handle goes forward`,`Leaning far back and pulling with body momentum`,`Shrugging your shoulders toward your ears`,`Pulling only with your arms without moving your shoulder blades`],breathing:`Breathe in as you extend your arms forward and out as you row the handle to your body.`,steps:[`Sit at the cable station and grab the V-handle with a neutral grip.`,`Plant your feet firmly, knees soft, and sit upright with straight arms.`,`Pull your shoulder blades back and down.`,`Row the handle back with your elbows to your upper belly or lower chest.`,`Let your arms extend forward again under control.`]},"reverse-grip-machine-lat-pulldown":{cues:[`Chest up`,`Pull your elbows down`,`Keep your wrists straight`,`Control the return`],mistakes:[`Leaning far back so it turns into a row`,`Pulling the handles behind your neck`,`Shrugging your shoulders toward your ears`,`Letting the weight slam back at the top`],breathing:`Breathe in as the handles go up and out as you pull them to your chest.`,steps:[`Adjust the seat so your knees sit firmly under the pads and your feet are flat on the floor.`,`Grab the handles with an underhand grip about shoulder-width apart.`,`Sit upright, chest up, arms fully extended at the top.`,`Pull the handles down and back to your upper chest with your elbows.`,`Let the handles rise under control until your arms are extended.`]},"dumbbell-incline-row":{cues:[`Lead with your elbows`,`Keep your chest on the pad`,`Squeeze your shoulder blades together`,`Lower under control`],mistakes:[`Shrugging your shoulders toward your ears`,`Yanking the dumbbells with body momentum`,`Flaring your elbows out to the sides`,`Lifting your chest off the bench at the top`],breathing:`Breathe in as you lower the dumbbells and out as you row to your ribs.`,steps:[`Set an incline bench to a medium angle and lie chest-down on it, feet on the floor.`,`Hold a dumbbell in each hand, arms hanging straight down, palms facing each other.`,`Brace your core and pull your shoulders back and down.`,`Row the dumbbells to your lower ribs by bending your elbows.`,`Lower them under control until your arms are extended.`]},"barbell-drag-curl":{cues:[`Keep the bar close to your body`,`Pull your elbows back`,`Chest upright`,`Lower under control`],mistakes:[`Swinging the bar forward away from your body`,`Bending your wrists back as you lift`,`Rocking your torso to start the curl`,`Flaring your elbows out to the sides`],breathing:`Breathe in at the bottom, out as you pull the bar up, and in again as you lower.`,steps:[`Stand hip-width apart holding the barbell in an underhand grip at your thighs.`,`Pull your shoulders back slightly, elbows stay behind your torso.`,`Drag the bar up close to your body as your elbows move back.`,`Lift it to your upper belly or lower chest.`,`Lower it slowly along the same path until your arms are extended.`]},"dumbbell-alternate-seated-biceps-curl":{cues:[`Keep your elbows still`,`Rotate your palm upward as you curl`,`Do not swing the weights`,`Brace your core`],mistakes:[`Using momentum`,`Flaring your elbows out`,`Rocking your torso`,`Moving both arms at the same time`],breathing:`Breathe out as you curl up and in as you lower.`,steps:[`Sit with your back against the backrest, feet flat on the floor.`,`Hold the dumbbells at your sides, palms facing your body.`,`Curl one dumbbell up, rotating your palm upward as you go.`,`Lower it and switch arms.`,`Keep your back straight and your elbows close to your body.`]},"cable-lying-triceps-extension":{cues:[`Keep your elbows in`,`Keep your upper arms still`,`Move only at the elbow`,`Finish with straight arms`],mistakes:[`Flaring your elbows wide to the sides`,`Letting your upper arms drift back so it turns into a pullover`,`Lowering the rope behind your head instead of to your forehead`,`Bouncing at the bottom instead of controlling the cable`],breathing:`Breathe in as you lower the rope to your forehead and out as you extend your elbows.`,steps:[`Attach a rope to the low cable and set a flat bench in line with the pulley.`,`Lie on your back with your head toward the cable and hold the rope with a neutral grip.`,`Press the rope over your chest with straight arms.`,`Bend your elbows with still upper arms and lower the rope to your forehead.`,`Extend your elbows and bring the rope back over your chest.`]},"single-arm-pushdown":{cues:[`Keep your elbow still`,`Upper arm stays horizontal`,`Fully extend your arm`,`Move only at the elbow`],mistakes:[`Letting your elbow move up and down during the rep`,`Rotating your torso to move the handle`,`Letting your upper arm sink instead of keeping it horizontal`,`Using momentum and letting the cable snap back`],breathing:`Breathe in as you bend your elbow and bring the handle in, and out as you extend your arm.`},"dumbbell-close-grip-press":{cues:[`Keep your elbows close to your body`,`Keep the dumbbells touching`,`Press through your palms`,`Control the lowering`],mistakes:[`Flaring your elbows out`,`Letting the dumbbells drift apart`,`Arching your lower back too much`,`Lowering the weights too deep`],breathing:`Breathe in as you lower the dumbbells and out as you press up.`,steps:[`Lie flat on the bench with a dumbbell in each hand.`,`Hold the dumbbells together over your chest, palms facing each other.`,`Lower them to your breastbone with your elbows close to your body.`,`Pause briefly when your elbows reach about 90 degrees.`,`Press the dumbbells back up by extending your arms.`]},"dumbbell-bar-grip-sumo-squat":{cues:[`Knees out`,`Keep your chest upright`,`Push your hips back`,`Press through your heels`],mistakes:[`Letting your knees fall inward`,`Rounding your back`,`Squats that are too shallow`],breathing:`Breathe in as you lower and out as you stand up.`,steps:[`Stand with a wide stance, toes turned out.`,`Hold the dumbbell vertically between your legs.`,`Keep your chest upright and brace your core.`,`Squat down and push your knees out.`,`Press back up through your heels.`]},"close-feet-leg-press":{cues:[`Keep your knees in line with your toes`,`Do not lock out your knees`,`Lower under control`,`Keep your back and hips on the pad`],mistakes:[`Letting your knees fall inward`,`Lifting your heels`,`Shortening the range of motion`],breathing:`Breathe out as you press up and in as you lower.`,steps:[`Sit in the leg press with your feet close together on the platform.`,`Adjust the seat and foot position so it is comfortable and safe.`,`Release the safety latch and hold on to the handles.`,`Extend your knees and press the weight up.`,`Lower the platform slowly back to the start position.`]},"dumbbell-deadlift":{cues:[`Hips back first`,`Keep the dumbbells close to your body`,`Chest up`,`Stand tall at the top`],mistakes:[`Rounding your lower back as the dumbbells lower`,`Letting the dumbbells drift far in front of your legs`,`Dropping straight down into the knees instead of pushing your hips back`,`Locking your knees stiffly or bending them too much`],breathing:`Breathe in as you lower the dumbbells under control and out as you stand up through your feet.`,steps:[`Stand hip- to shoulder-width apart with a dumbbell in each hand in front of your thighs.`,`Brace your core, pull your shoulders back and keep your arms straight.`,`Push your hips back, bend your knees slightly and lower the dumbbells close along your legs.`,`Go down with a straight back to about mid-shin.`,`Drive up through your feet and push your hips forward until you stand tall.`]},"dumbbell-lying-femoral":{cues:[`Keep your hips down`,`Squeeze at the top`,`Control the lowering`,`Actively use your hamstrings`],mistakes:[`Lifting your hips`,`Letting the dumbbell slip`,`Using momentum`],breathing:`Breathe out as you curl up and in as you lower.`,steps:[`Lie face down on the bench with your legs extended and the dumbbell between your feet.`,`Hold on to the bench for stability.`,`Tense your hamstrings and curl the dumbbell toward your glutes.`,`Pause briefly at the top.`,`Lower the dumbbell under control back to the start position.`]},"machine-glute-kickback":{cues:[`Lead with your heel`,`Keep your core braced`,`No arching of the lower back`,`Squeeze your glutes at the top`],mistakes:[`Lifting with your lower back`,`Flinging your leg with momentum`,`Not controlling the lowering phase`],breathing:`Breathe out as you kick back and in as you return.`},"dumbbell-seated-calf-raise":{cues:[`Press through your big toe`,`Raise your heels straight up`,`Use the full range of motion at the ankle`,`Control the lowering`],mistakes:[`Bouncing your heels at the bottom instead of lowering under control.`,`Tipping your ankles inward or outward as you lift.`,`Placing the dumbbell too close to your knees so it slips during the set.`,`Using a very short range of motion and not lowering your heels below the step.`],breathing:`Breathe in as you lower your heels and out as you press up onto the balls of your feet.`,steps:[`Sit on a bench or chair with your knees bent, the balls of your feet on a small raised surface, heels hanging free.`,`Lay a dumbbell across your thighs just above your knees and hold it with both hands.`,`Let your heels sink until you feel a stretch in your calves.`,`Press up through the balls of your feet as high as you can and pause briefly at the top.`,`Lower your heels under control and repeat.`]},"v-up":{cues:[`Lift with your abs`,`Keep your legs straight`,`Reach for your toes`,`Control the lowering`],mistakes:[`Swinging your legs`,`Arching your lower back`,`Not engaging your abs properly`],breathing:`Breathe out as you come up and in as you lower.`,steps:[`Lie on your back with your arms extended overhead and your legs straight.`,`Brace your core and lift your legs and torso at the same time.`,`Reach for your feet with your hands at the top so you form a “V”.`,`Pause briefly and squeeze your abs.`,`Lower yourself slowly back to the start position.`]},"hanging-leg-hip-raise":{cues:[`Curl your pelvis up`,`Control the swinging`,`Ribs down`,`Lift your knees, not your shoulders`],mistakes:[`Swinging your body to start each rep`,`Shrugging your shoulders toward your ears`,`Dropping your legs as you lower`,`Lifting your knees only halfway without curling your hips`],breathing:`Breathe out as you lift your knees and curl your hips, and in as you lower into the hang.`,steps:[`Hang from the bar with both hands and let your body settle.`,`Pull your ribs down and brace your core to stop the swinging.`,`Bend your knees and lift them toward your chest by curling your hips up.`,`Lift until your thighs are at least horizontal.`,`Lower your legs under control back to a full hang.`]},"sit-up-on-exercise-ball":{cues:[`Keep your feet firmly on the floor`,`Do not pull on your neck`,`Keep your abs tensed throughout`,`No arching of the lower back`],mistakes:[`Using momentum`,`Your feet lift off the floor`,`The ball is not under your lower back`],breathing:`Breathe out as you sit up and in as you lower.`,steps:[`Sit on the exercise ball with your feet flat on the floor.`,`Walk your feet forward and roll until the ball supports your lower back.`,`Cross your arms over your chest or place your hands behind your head.`,`Brace your core and sit your torso up.`,`Lower yourself under control back to the start position.`]}},t={"bb-incline":{cues:[`Press your feet firmly into the floor`,`Chest up`,`Stack your wrists over your elbows`,`Press straight up`],mistakes:[`Flaring your elbows wide to the sides`,`Bouncing the bar off your chest`,`Lifting your feet or sliding around on the bench`,`Lowering the bar toward your neck or belly`],breathing:`Breathe in as you lower the bar to your chest, and breathe out as you press it back up.`},"machine-incline-chest":{cues:[`Press up and slightly forward`,`Keep your feet flat on the floor`,`Do not shrug your shoulders`,`Hold briefly at the top`],mistakes:[`Flaring your elbows too far`,`Fully locking out your elbows`,`Arching your back and lifting off the seat`,`Gripping the handles unevenly`],breathing:`Breathe out as you press up, and breathe in as you return.`},"db-fly":{cues:[`Imagine hugging a wide barrel`,`Keep your elbows slightly bent`,`Lower under control`,`Squeeze your chest together at the top`],mistakes:[`Bending and straightening your elbows like in a press`,`Lowering the dumbbells too far below chest height`,`Bringing the dumbbells together by pulling your shoulders forward`,`Dropping your arms quickly instead of controlling the arc`],breathing:`Breathe in as you lower the dumbbells out to the sides, and breathe out as you bring them back together over your chest.`},"decline-bb":{cues:[`Press your shoulders into the bench`,`Stack your wrists over your forearms`,`Lower to the lower chest`,`Press straight up`],mistakes:[`Bouncing the bar off your chest`,`Flaring your elbows wide to the sides`,`Letting your wrists bend under the bar`,`Pressing the bar toward your face instead of over your chest`],breathing:`Breathe in as you lower the bar to your chest, and breathe out as you press it back up.`},"seated-db-ohp":{cues:[`Keep your back against the pad`,`Do not arch your lower back`,`Press straight up`,`Elbows under your wrists`],mistakes:[`Excessive arching of the lower back`,`Lowering the weights too fast`,`Letting your elbows sink too low`,`Pushing the weights out in front of you`],breathing:`Breathe out as you press up, and breathe in as you lower.`},"db-lateral":{cues:[`Lead with your elbows`,`Stop at shoulder height`,`Keep your shoulders down`,`Elbows slightly bent`],mistakes:[`Shrugging your shoulders toward your ears`,`Heaving the dumbbells up with momentum from your torso`,`Raising your hands far above shoulder height`,`Straightening your elbows so it turns into a front raise`],breathing:`Breathe out as you raise the dumbbells to the sides, and breathe in as you lower them under control.`},"db-front-raise":{cues:[`Raise up to shoulder height`,`Keep your ribs down`,`Lead with your hands`,`Do not shrug your shoulders`],mistakes:[`Swinging the dumbbells up with your hips or torso`,`Raising the weights above shoulder height`,`Shrugging your shoulders toward your ears`,`Bending your elbows more and more as you lift`],breathing:`Breathe out as you raise the dumbbells, and breathe in as you lower them under control.`},"reverse-pec-deck":{cues:[`Lead with your elbows`,`Keep your chest against the pad`,`Elbows slightly bent`,`Squeeze your shoulder blades together`],mistakes:[`Shrugging your shoulders toward your ears`,`Straightening your elbows so it turns into a pressing motion`,`Lifting your chest off the pad`,`Yanking the handles back with momentum`],breathing:`Breathe out as you pull the handles back, and breathe in as you return to the start position.`},pullup:{cues:[`Lead with your chest`,`Do not swing`,`Full range of motion`,`Elbows down and back`],mistakes:[`Using momentum`,`Half reps`,`Shrugging your shoulders`],breathing:`Breathe out as you pull up and in as you lower.`},"lat-pulldown":{cues:[`Pull your elbows down`,`Chest up`,`Do not swing`,`Control the weight`],mistakes:[`Using momentum or swinging your body`,`Pulling your shoulders up`,`Not fully extending your arms`,`Pulling the bar behind your neck`],breathing:`Breathe out as you pull the bar down, and breathe in as you return to the start position.`},"db-row":{cues:[`Straight back`,`Lead with your elbows`,`Brace your core`,`Squeeze your shoulder blades together`],mistakes:[`Rounding your back`,`Yanking the weights up`,`Not fully extending your arms`,`Pulling too much with your biceps`],breathing:`Breathe out as you row up, and breathe in as you lower.`},"t-bar-row":{cues:[`Squeeze your shoulder blades together`,`Drive your elbows back`,`Keep your chest on the pad`,`Get a full stretch at the bottom`],mistakes:[`Arching your lower back`,`Not fully extending your arms`,`Letting the weight bounce`,`Letting your shoulders roll forward`],breathing:`Breathe out as you row up, and breathe in as you lower.`},"inverted-row":{cues:[`Keep your body in a line`,`Drive your elbows back`,`Squeeze your shoulder blades together`,`Keep your shoulders down`],mistakes:[`Your hips sag or pike instead of staying straight`,`Shrugging your shoulders toward your ears`,`Pulling with bent wrists and a loose grip`,`Dropping your body quickly on the way down`],breathing:`Breathe in as you lower yourself away from the handles, and breathe out as you pull your chest toward them.`},"db-shrug":{cues:[`Shrug your shoulders straight up`,`Keep your arms long`,`Relax your neck`,`Lower under control`],mistakes:[`Rolling your shoulders instead of going straight up and down.`,`Bending your elbows so it turns into an upright row.`,`Leaning your torso forward or back to swing the dumbbells.`,`Pushing your head forward as your shoulders rise.`],breathing:`Breathe out as you shrug your shoulders up, and breathe in as you lower them again.`},"back-extension":{cues:[`Keep your back straight`,`Hinge from the hips`,`Squeeze your glutes`,`Do not overextend your spine`],mistakes:[`Rounding your back`,`Overextending at the top`,`Using momentum`],breathing:`Breathe out as you come up and in as you lower.`},"bb-curl":{cues:[`Keep your elbows at your sides`,`Lift with your biceps`,`Keep your wrists straight`,`Lower under control`],mistakes:[`Swinging your torso to get the bar moving`,`Letting your elbows drift forward as you lift`,`Bending your wrists back instead of keeping them neutral`,`Dropping the bar quickly on the way down`],breathing:`Breathe out as you curl the bar up, and breathe in as you lower it under control.`},"hammer-curl":{cues:[`Keep your elbows tucked in`,`Curl across your body, not straight up`,`Keep your wrists neutral`,`Do not swing the weight`],mistakes:[`Swinging or leaning your torso back to lift the dumbbell`,`Letting your elbow drift forward away from your ribs`,`Rotating your wrist so your palm faces up at the top`,`Dropping the dumbbell quickly instead of lowering it under control`],breathing:`Breathe out as you curl the dumbbell across your body, and breathe in as you lower it again.`},"concentration-curl":{cues:[`Fix your elbow against your thigh`,`Bend only at the elbow`,`Keep your palm facing up`,`Lower under control`],mistakes:[`Lifting your elbow off your thigh while curling`,`Swinging your torso to lift the dumbbell`,`Cutting the rep short and not lowering fully`,`Bending your wrist back instead of keeping it neutral`],breathing:`Breathe in as you lower the dumbbell, and breathe out as you curl it up.`},"overhead-cable-ext":{cues:[`Keep your upper arms still`,`Elbows in`,`Fully extend`,`Do not arch your lower back`],mistakes:[`Moving your upper arms`,`Flaring your elbows out`,`Overextending or swinging your back`],breathing:`Breathe out as you extend and in as you bend your elbows.`},"db-skullcrusher":{cues:[`Keep your elbows in`,`Upper arms stay still`,`Bend only at the elbow`,`Stack your wrists over your elbows`],mistakes:[`Your elbows flare out as you lower the dumbbells.`,`Your upper arms drift back or forward during the rep.`,`The dumbbells sink too far behind your head instead of beside your forehead.`,`Your wrists bend back instead of staying straight.`],breathing:`Breathe in as you lower the dumbbells to your forehead, and breathe out as you extend your elbows and press them back up.`},"machine-tri":{cues:[`Keep your elbows in`,`Upper arms stay still`,`Move only at the elbow`,`Control both directions`],mistakes:[`Your elbows flare wide to the sides.`,`Your shoulders roll forward and your chest collapses.`,`The handles are dropped quickly toward your head.`,`Your upper arms swing back and forth during the rep.`],breathing:`Breathe in as you bend your elbows and lower the handles, and breathe out as you extend your arms and push them away.`},"band-pushdown":{cues:[`Fix your elbows at your sides`,`Move only your forearms`,`Stand upright`,`Squeeze at the end`],mistakes:[`Your upper arms swing back and forth`,`Your elbows flare away from your torso`,`Leaning your body weight onto the band`,`Not fully extending your elbows`],breathing:`Breathe out as you push the band down, and breathe in as you return to the start position.`},"bb-squat":{cues:[`Chest up`,`Straight back`,`Press through your heels`,`Guide your knees in line with your toes`],mistakes:[`Knees cave inward`,`Rounding your lower back`,`Heels lift off the floor`],breathing:`Breathe in as you lower and out as you come back up.`},"leg-press":{cues:[`Press your lower back into the pad`,`Do not lock out your knees`,`Feet flat with even pressure`,`Control the lowering`],mistakes:[`Letting your knees tip inward or outward`,`Lifting your hips off the seat`,`Locking out your knees`,`Using too much weight`],breathing:`Breathe out as you press up, and breathe in as you lower.`},"walking-lunge":{cues:[`Chest upright`,`Front heel stays on the floor`,`Guide your knees in line with your toes`,`Go straight down`],mistakes:[`Taking too short a step so the front knee shoots far past your toes.`,`Leaning your torso forward as you lower.`,`Lifting your front heel off the floor.`,`Pushing off the back foot instead of driving through the front leg.`],breathing:`Breathe in as you lower into the lunge, and breathe out as you rise again.`},"db-rdl":{cues:[`Hips back, not down`,`Guide the dumbbells close to your body`,`Keep your back straight the whole time`,`Feel the stretch in your hamstrings`],mistakes:[`Bending your knees too much so it turns into a squat`,`Letting the dumbbells drift away from your body`,`Rounding your lower back as you lower`,`Looking up and overextending your neck`],breathing:`Breathe in as you hinge at the hips and lower the dumbbells, and breathe out as you drive your hips forward and stand up.`},"band-leg-curl":{cues:[`Keep your hips down`,`Point your toes away`,`Squeeze your hamstrings at the top`,`Control the lowering phase`],mistakes:[`Lifting your hips off the floor`,`Using momentum`,`Letting the band snap back`],breathing:`Breathe out as you curl and in as you lower.`},"band-abduction":{cues:[`Chest up`,`Keep your standing leg stable`,`Move slowly`,`Feel your glutes working`],mistakes:[`Leaning your torso to the side`,`Poor balance`,`Letting the band snap back`],breathing:`Breathe out as you raise your leg and in as you return.`},"smith-calf":{cues:[`Move only at the ankle`,`Keep your legs straight (but not locked)`,`Control the movement`,`Hold briefly at the top`],mistakes:[`Bouncing with momentum`,`Using only part of the range of motion`,`Letting your ankles roll outward or inward`],breathing:`Breathe out as you go up and in as you lower.`},"cable-crunch":{cues:[`Ribs toward hips`,`Keep your hips still`,`Curl in, do not fold from the hips`,`Keep your neck neutral`],mistakes:[`Pulling the rope down with your arms instead of curling your torso`,`Sitting your hips back so it turns into a hip hinge`,`Jerking up and dropping the weight stack between reps`,`Lifting your chest too high and losing ab tension at the top`],breathing:`Breathe out as you curl into the crunch, and breathe in as you slowly return to the start position.`},"side-plank":{cues:[`Keep your body straight`,`Elbow directly under your shoulder`,`Squeeze your glutes`,`Do not let your hips sag`],mistakes:[`Letting your hips sink`,`Letting your shoulder collapse inward`,`Twisting your torso`],breathing:`Keep breathing steadily during the hold.`},"db-side-bend":{cues:[`Bend only to the side`,`Keep your chest upright`,`Brace your core`,`Move slowly and under control`],mistakes:[`Twisting your torso as you bend`,`Leaning forward instead of to the side`,`Shrugging the loaded shoulder`,`Using momentum to come back up`],breathing:`Breathe in as you bend to the side, and breathe out as you straighten up again.`},"c-elliptical":{cues:[`Chest up`,`Distribute your weight evenly`,`Smooth, controlled motion`,`Lightly brace your core`],mistakes:[`Leaning too far forward or back`,`Working only with your legs or only with your arms`,`Jerky, rushed movements`],breathing:`Breathe rhythmically and deeply throughout the workout.`},"dumbbell-decline-fly-45-degree-1":{cues:[`Arms slightly bent`,`Wide arc of motion`,`Do not overstretch`,`Squeeze your chest together at the top`],mistakes:[`Straightening your arms`,`Lowering the dumbbells too deep`,`Using too much weight`,`Rushing the rep`],breathing:`Breathe in as you open your arms, and breathe out as you bring the weights together.`,steps:[`Set the bench to about a 45-degree decline and secure your feet.`,`Lie back with your arms extended over your chest, elbows slightly bent.`,`Lower the dumbbells out to the sides in a wide arc.`,`Hold the stretch briefly at the bottom.`,`Bring the dumbbells back to the start position, squeezing your chest together.`]},"dumbbell-incline-hammer-press":{cues:[`Press up over your upper chest`,`Palms face each other`,`Press your shoulders into the bench`,`Stack your wrists over your elbows`],mistakes:[`Flaring your elbows wide to the sides`,`Letting the dumbbells drift back over your face`,`Clanking the dumbbells together at the top`,`Arching your lower back and lifting your hips`],breathing:`Breathe in as you lower the dumbbells to chest height, and breathe out as you press them up.`,steps:[`Set an incline bench and sit down with a dumbbell on each thigh.`,`Lie back and bring the dumbbells to chest height, palms facing each other.`,`Plant your feet firmly, pull your shoulder blades into the bench and keep your wrists over your elbows.`,`Press the dumbbells up until your arms are extended over your upper chest.`,`Lower the dumbbells under control back to chest height without letting them bounce.`]},"deep-push-ups":{cues:[`Keep your elbows at a 45-degree angle`,`Lower your chest below hand height`,`Keep your body in a line`,`Brace your core`],mistakes:[`Sagging hips`,`Flaring your elbows`,`Not going deep enough`,`Rounding your shoulders forward`],breathing:`Breathe in as you lower yourself, and breathe out as you push up.`,steps:[`Support your hands shoulder-width apart on raised surfaces.`,`Get into a plank position, core braced, body straight.`,`Lower your chest between your hands, deeper than hand height.`,`Hold briefly at the bottom and feel the deep stretch in your chest.`,`Push up powerfully until your arms are extended.`]},"cable-one-arm-lateral-raise":{cues:[`Lead with your elbow`,`Keep your shoulders level`,`Raise up to shoulder height`,`Lower under control`],mistakes:[`Shrugging the working shoulder toward your ear`,`Swinging your torso to start the rep`,`Turning the movement into a front raise`,`Raising your hand far above shoulder height`],breathing:`Breathe out as you raise your arm to the side, and breathe in as you lower it under control.`,steps:[`Stand sideways to the cable and grab the handle with your outer hand.`,`Step away until the cable is taut, your arm hangs at your side, elbow slightly bent.`,`Brace your core and keep your shoulders level.`,`Raise your arm out to the side to about shoulder height without shrugging.`,`Lower the handle under control and switch sides after the reps.`]},"dumbbell-upright-row":{cues:[`Lead with your elbows`,`Keep the dumbbells close to your body`,`Shoulders down and back`,`Pull up to your upper chest`],mistakes:[`Pulling the dumbbells up to your chin`,`Bending your wrists sharply at the top`,`Swinging your torso to start the weight`,`Your hands rise higher than your elbows`],breathing:`Breathe out as you pull the dumbbells up, and breathe in as you lower them again.`,steps:[`Stand upright with a dumbbell in front of each thigh, palms facing your body.`,`Brace your core and keep your chest up.`,`Pull the dumbbells up close to your body, elbows lead up and out.`,`Hold briefly at about upper-chest height, then lower under control to your thighs.`]},"barbell-underhand-bent-over-row":{cues:[`Keep your back straight`,`Pull with your elbows`,`Squeeze your shoulder blades together`,`Keep your wrists neutral`],mistakes:[`Rounding your lower back`,`Flaring your elbows excessively`,`Using momentum`],breathing:`Breathe out as you row up and in as you lower.`,steps:[`Stand hip-width apart with the barbell on the floor in front of you.`,`Hinge forward at the hips, back straight, and grip the bar underhand.`,`Let the bar hang with straight arms below your shoulders.`,`Row the barbell to your torso, elbows close to your body.`,`Lower the barbell under control back to the start position.`]},"machine-pulldown":{cues:[`Pull your elbows toward your ribs`,`Chest up`,`Shoulders down, not shrugged`,`Control the way up`],mistakes:[`Pulling the bar behind your neck`,`Swinging your torso back to start the rep`,`Shrugging your shoulders at the top`,`Stopping too early and not fully extending your arms`],breathing:`Breathe in as the bar goes up, and breathe out as you pull it to your upper chest.`},"reverse-grip-pull-up":{cues:[`Chest to the bar`,`Drive your elbows down`,`Do not swing`,`Fully extend your arms`],mistakes:[`Not extending your arms`,`Using momentum`,`Craning your neck over the bar`],breathing:`Breathe out as you pull up and in as you lower.`,steps:[`Grip the bar underhand (palms facing you), about shoulder-width apart.`,`Hang with straight arms and engaged shoulder blades.`,`Pull your chest to the bar, leading with your elbows.`,`Bring your chin over the bar and squeeze at the top.`,`Lower yourself under control to the start position.`]},"lever-reverse-t-bar-row":{cues:[`Keep your chest against the pad`,`Lead with your elbows`,`Squeeze your shoulder blades together`,`Lower under control`],mistakes:[`Shrugging your shoulders toward your ears`,`Bouncing your chest off the pad to move the handles`,`Rounding your upper back at the start`,`Yanking the weight and dropping it quickly again`],breathing:`Breathe out as you pull the handles to your chest, and breathe in as you return them under control.`,steps:[`Adjust the seat or chest pad so the handles are at about mid-chest height when you reach forward.`,`Press your chest firmly against the pad and place your feet flat on the platform.`,`Grip the handles overhand and extend your arms without rounding your shoulders.`,`Pull the handles to your chest, elbows lead back and slightly out.`,`Squeeze your shoulder blades together at the end and release the handles under control until your arms are extended.`]},"cable-one-arm-curl":{cues:[`Keep your elbow fixed`,`Palm stays facing up`,`Stand upright`,`Lower under control`],mistakes:[`Your elbow swings forward as you curl`,`Your shoulder is shrugged toward your ear`,`Your torso leans back to move the weight`,`The handle drops quickly on the way down`],breathing:`Breathe out as you curl the handle up, and breathe in as you lower it again.`,steps:[`Stand sideways to the cable and grab the handle with one hand, palm up.`,`Step away until the cable is taut and stand upright with your elbow at your side.`,`Curl the handle up by bending only your elbow.`,`Squeeze your biceps briefly at the top and lower the handle slowly until your arm is extended.`,`Do all reps with one arm, then switch sides.`]},"dumbbell-seated-preacher-curl":{cues:[`Press your upper arm firmly into the pad`,`Bend only at the elbow`,`Lower under control`,`Squeeze at the top`],mistakes:[`Your upper arm lifts off the pad while curling`,`Swinging the dumbbell instead of moving it smoothly`,`Stopping too early and not lowering almost to full extension`,`Bending your wrist back as you lift`],breathing:`Breathe out as you curl the dumbbell up, and breathe in as you lower it under control.`,steps:[`Sit at the preacher bench and place your feet flat on the floor.`,`Hold a dumbbell palm up and rest the back of your upper arm firmly on the pad.`,`Start with your arm almost straight, the dumbbell hanging just above the bottom of the pad.`,`Curl the dumbbell up, your upper arm stays on the pad, and squeeze your biceps briefly at the top.`,`Lower it slowly back to almost full extension, then switch sides.`]},"dumbbell-incline-triceps-extension":{cues:[`Keep your elbows in`,`Upper arms stay still`,`Lower under control`,`Finish straight overhead at the top`],mistakes:[`Your elbows flare wide to the sides.`,`Your upper arms drift back and it turns into a press.`,`Lowering only a few centimeters behind your head.`,`Arching your lower back off the bench.`],breathing:`Breathe in as you lower the dumbbells behind your head, and breathe out as you extend your elbows and bring them overhead.`,steps:[`Sit leaning back on an incline bench with a dumbbell in each hand.`,`Press the dumbbells overhead, palms facing each other.`,`Keep your elbows pointing up and close to your head.`,`Lower the dumbbells behind your head by bending only your elbows.`,`Extend your elbows and bring the dumbbells back overhead.`]},"band-overhead-triceps-extension":{cues:[`Elbows point forward`,`Upper arms stay still`,`Keep your ribs down`,`Fully extend your elbows`],mistakes:[`Your elbows flare out to the sides`,`Your lower back arches when the band goes overhead`,`Your upper arms drift forward and back`,`Doing only part of the movement instead of fully extending`],breathing:`Breathe in as you lower your hands behind your head, and breathe out as you extend your elbows overhead.`,steps:[`Stand hip-width apart on the middle of the band and hold one end in each hand.`,`Raise your hands overhead and bend your elbows so your hands go behind your head.`,`Keep your upper arms close to your ears and brace your core.`,`Extend your elbows and press the band overhead until your arms are fully straight.`,`Hold briefly at the top and slowly bend your elbows back behind your head.`]},"wrist-curl":{cues:[`Move only your wrists`,`Palms face each other`,`Forearms stay supported`,`Lower under control`],mistakes:[`Lifting your forearms off your thighs to swing the dumbbells up`,`Rotating your palms up or down while curling`,`Bouncing the dumbbells at the bottom`,`Using your shoulders or elbows to help`],breathing:`Breathe out as you curl your wrists up, and breathe in as you lower the dumbbells again.`},"dumbbell-single-leg-squat":{cues:[`Chest up`,`Sit your glutes back`,`Your knee points forward`,`Control the descent`],mistakes:[`Putting the raised foot on the floor between reps`,`Rounding your back at the bottom`,`Letting the standing-leg knee cave inward`,`Sinking too fast and losing your balance`],breathing:`Breathe in as you lower yourself, and breathe out as you rise again.`,steps:[`Stand upright with a dumbbell in each hand at your sides.`,`Shift your weight onto one foot and raise the other leg straight out in front.`,`Brace your core and bend your standing-leg knee and hip to lower yourself under control.`,`Keep the raised leg above the floor and go as deep as you can stay stable.`,`Drive back up through your standing foot and switch sides after all reps.`]},"sled-45-degree-leg-wide-press":{cues:[`Press through your heels`,`Keep your knees in line with your toes`,`Do not lock out your knees at the top`,`Keep your lower back flat`],mistakes:[`Letting your knees cave inward`,`Rounding your lower back`,`Half reps or too short a range`,`Locking out your knees at the top`],breathing:`Breathe in as you lower the platform, and breathe out as you press it back up.`,steps:[`Adjust the seat and load the desired weight.`,`Sit with your back and head against the pad, feet flat and wide on the platform.`,`Release the safety handles and grab the side handles.`,`Bend your knees and lower the platform until your thighs reach about 90 degrees or a bit deeper.`,`Press up through your heels and extend your legs without locking out your knees.`]},"kettlebell-deadlift":{cues:[`Keep your back straight`,`Press through your heels`,`Squeeze your glutes`,`Keep the kettlebell close to your body`],mistakes:[`Rounding your lower back`,`Letting the kettlebell drift away from your body`,`Locking out your knees too early`,`Shrugging your shoulders`],breathing:`Breathe out as you stand up and in as you lower.`,steps:[`Place the kettlebell between your feet and stand hip-width apart.`,`Bend your hips and knees, back straight, chest up.`,`Grab the kettlebell handle with both hands.`,`Press up through your heels and fully extend your hips and knees.`,`Lower the kettlebell under control by pushing your hips back.`]},"lever-kneeling-leg-curl":{cues:[`Keep your hips firmly down`,`Curl from your knees`,`Move slowly on the way down`,`Squeeze your hamstrings at the top`],mistakes:[`Lifting your hips off the pad while curling`,`Swinging your legs to start each rep`,`Stopping too early and not extending your knees at the bottom`,`Letting your ankles slip out of the pads`],breathing:`Breathe out as you curl your heels up, and breathe in as you return to the start position.`,steps:[`Adjust the machine so your knees sit at the pivot and your ankles sit securely under the pads.`,`Kneel on the pad facing the machine, brace your torso on the support and grab the handles.`,`Start with your legs extended behind you and keep your hips still.`,`Curl your heels toward your glutes by bending your knees against the pads.`,`Hold briefly at the top, squeeze your hamstrings and lower the pads under control until your legs are extended.`]},"band-pull-through":{cues:[`Push your hips back`,`Keep your ribs down`,`Stand tall at the top`,`Squeeze your glutes hard`],mistakes:[`Squatting down instead of pushing your hips back`,`Rounding your lower back as you hinge forward`,`Letting the band pull you backward at the top`,`Bending your knees too much so it shifts to your quads`],breathing:`Breathe in as you hinge back, and breathe out as you drive your hips forward and stand up.`,steps:[`Anchor the band at floor level and run it between your legs.`,`Turn away from the anchor and walk forward until the band is taut.`,`Stand about hip-width apart and bend your knees slightly.`,`Push your hips back and hinge forward, the band runs behind you.`,`Go until you stretch your hamstrings, back straight, then drive your hips forward and squeeze your glutes at the top.`]},"dumbbell-single-leg-calf-raise":{cues:[`Press through your big toe`,`Go straight up`,`Lower under control`,`Keep your hips level`],mistakes:[`Bouncing at the bottom instead of lowering under control`,`Letting your ankle roll inward or outward on the way up`,`Bending your standing-leg knee to help lift`,`Pulling your body up with your support hand`],breathing:`Breathe in as you lower your heel, and breathe out as you press up onto your toes.`,steps:[`Stand with one foot on the edge of a step, the ball of your foot on the step, your heel hanging free.`,`Hold a dumbbell in one hand and lightly steady yourself with the other on a wall or railing.`,`Lift your other foot off the step and straighten your standing leg.`,`Press up through the ball of your foot and raise your heel as high as you can.`,`Hold briefly at the top and slowly lower your heel below the step until you stretch your calf, then switch sides.`]},"lying-floor-leg-raise":{cues:[`Brace your core`,`Keep your lower back on the floor`,`Control the descent`,`Do not swing`],mistakes:[`Arching your lower back`,`Using momentum`,`Resting your feet on the floor between reps`],breathing:`Breathe out as you raise your legs and in as you lower.`,steps:[`Lie flat on your back with your legs extended.`,`Place your arms at your sides or under your hips.`,`Raise your legs up with straight knees.`,`Lift until your hips come slightly off the floor.`,`Lower your legs slowly without touching the floor.`]},"twisting-crunch":{cues:[`Rotate from your torso`,`Elbow to knee`,`Do not pull on your neck`,`Keep your lower back on the floor`],mistakes:[`Pulling on your head or neck`,`Not rotating enough`,`Lifting your lower back`],breathing:`Breathe out as you crunch and twist, and in as you return.`,steps:[`Lie on your back, knees bent, feet flat.`,`Place your hands loosely behind your head.`,`Curl up and rotate your torso so one shoulder moves toward the opposite knee.`,`Return to the start position and repeat to the other side.`,`Alternate sides on every rep.`]},"cable-standing-crunch":{cues:[`Ribs toward hips`,`Keep your hips still`,`Curl in, do not fold from the hips`,`Brace your abs`],mistakes:[`Folding forward at the hips instead of curling your spine`,`Pulling the handle down with your arms`,`Standing too upright and barely moving your torso`,`Letting the weight yank you back up`],breathing:`Breathe in at the top, breathe out as you curl in, and breathe in as you return under control.`,steps:[`Set the cable high and stand with your back to the machine.`,`Hold the attachment with both hands at the sides of your head and bend your knees slightly.`,`Brace your core and keep your hips mostly still.`,`Curl your ribcage toward your pelvis, your elbows move toward your thighs.`,`Hold briefly at the bottom, squeeze your abs and slowly curl back to the start position.`]}},n={"db-incline":{cues:[`Stack your wrists over your elbows`,`Press your feet firmly into the floor`,`Lower under control`,`Press over your upper chest`],mistakes:[`Flaring your elbows wide out`,`Letting the dumbbells drift toward your face`,`Bouncing the dumbbells off your chest at the bottom`,`Lifting your lower back off the bench (arching)`],breathing:`Breathe in as you lower the dumbbells and out as you press up.`},"pec-deck":{cues:[`Keep your elbows slightly bent`,`Squeeze your chest at the turning point`,`Keep your back against the pad`,`Control the way back`],mistakes:[`Locking out your elbows`,`Arching your lower back`,`Using too much weight`],breathing:`Breathe out as you bring your arms together and in as you open.`},pushup:{cues:[`Keep your body straight`,`Brace your core`,`Elbows at a 45-degree angle`,`Lower under control`],mistakes:[`Letting your hips sag`,`Flaring your elbows too far`,`Incomplete range of motion`],breathing:`Breathe in as you lower and out as you press up.`},"bb-ohp":{cues:[`Brace your core firmly`,`Press the bar in a straight line`,`Do not arch your lower back`,`Extend your elbows at the top`],mistakes:[`Leaning back too far`,`Bouncing the bar off your shoulders`,`Flaring your elbows too far`,`Not lowering the bar to below your chin`],breathing:`Breathe out as you press up and in as you lower.`},"smith-ohp":{cues:[`Keep your ribs down`,`Press straight up`,`Wrists over your elbows`,`Feet flat and firmly planted`],mistakes:[`Lowering the bar behind your head`,`Flaring your elbows wide out`,`Lifting your lower back off the bench (arching)`,`Bending your wrists sharply backward`],breathing:`Breathe in as you lower the bar to shoulder height and out as you press it overhead.`},"cable-lateral":{cues:[`Lead with your elbow`,`Stop at shoulder height`,`Keep your neck relaxed`,`Raise under control`],mistakes:[`Shrugging your shoulder toward your ear`,`Swinging your torso to lift the handle`,`Turning the movement into a front raise`,`Raising your hand far above shoulder height`],breathing:`Breathe out as you raise the handle to the side and in as you lower.`},"cable-front-raise":{cues:[`Keep your core braced`,`Lift from the shoulder, not from the hand`,`Do not swing`,`Control the lowering`],mistakes:[`Using momentum`,`Shrugging your shoulder`,`Overextending at the top`],breathing:`Breathe out as you raise and in as you lower.`},"face-pull":{cues:[`Lead with your elbows`,`Chest up, back straight`,`Pull your shoulders back`,`Control the way back`],mistakes:[`Standing fully upright so it turns into a normal cable row`,`Shrugging your shoulders toward your ears while pulling`,`Pulling mainly with your hands and curling the rope in`,`Rounding your upper back on the return`],breathing:`Breathe in as you return the rope forward and out as you row the rope to your upper chest.`},"wide-grip-pullup":{cues:[`Keep your elbows open outward`,`Lead with your chest`,`Engage your lats`,`Do not swing`],mistakes:[`Half reps`,`Using momentum`,`Shrugging your shoulders`],breathing:`Breathe out as you pull up and in as you lower.`},"lat-pulldown-neutral":{cues:[`Lead with your elbows`,`Chest up`,`Do not swing backward`,`Squeeze your lats at the bottom`],mistakes:[`Leaning back too far`,`Using momentum`,`Not properly engaging your lats`,`Rounding your shoulders forward`],breathing:`Breathe out as you pull down and in as you return upward.`},"cable-row":{cues:[`Keep your back straight`,`Pull your elbows back`,`Squeeze your shoulder blades together`,`Do not lean and do not round your back`],mistakes:[`Curling your back`,`Using momentum`,`Letting your elbows flare out`],breathing:`Breathe out as you pull in and in as you extend forward.`},"chest-supported-db-row":{cues:[`Keep your chest on the bench`,`Elbows close to your body`,`Do not shrug your shoulders`,`Squeeze fully at the top`],mistakes:[`Lifting your chest off the bench`,`Rowing too much with your biceps`,`Shrugging your shoulders`],breathing:`Breathe out as you pull up and in as you lower.`},"band-row":{cues:[`Lead with your elbows`,`Chest up`,`Squeeze your shoulder blades together`,`Do not round your back`],mistakes:[`Rounding your back`,`Using momentum`,`Letting the band go slack between reps`],breathing:`Breathe out as you row and in as you return to the start position.`},"bb-shrug":{cues:[`Shoulders straight up`,`Arms stay long`,`Chest upright`,`Do not roll`],mistakes:[`Bending your elbows and curling the bar up.`,`Rolling your shoulders forward or back at the top.`,`Leaning back and swinging your torso to move the bar.`,`Pushing your head forward as your shoulders rise.`],breathing:`Breathe in before each rep, out as you shrug your shoulders up, and in again as you lower.`},"machine-back-ext":{cues:[`Brace before the movement`,`Move in an even arc`,`Keep your feet planted firmly`,`Return to an upright position`],mistakes:[`Using momentum and bouncing at the bottom`,`Making the range of motion short and hasty`,`Lifting or shifting your feet on the platform`,`Overextending far past the upright position at the top`],breathing:`Breathe in as you lean forward and out as you come up to the upright position.`},"db-curl":{cues:[`Fix your elbows at your sides`,`Curl, do not swing`,`Squeeze at the top`,`Lower under control`],mistakes:[`Swinging your torso to start the curl`,`Letting your elbows drift forward as you lift`,`Doing only part of the movement and not lowering fully`,`Bending your wrists back instead of keeping them neutral`],breathing:`Breathe out as you curl the dumbbells up and in as you lower.`},"preacher-curl":{cues:[`Keep your upper arms firmly on the pad`,`Bend only at the elbow`,`Curl up smoothly, lower more slowly`,`Keep your wrists neutral`],mistakes:[`Your upper arms lift off the pad as you curl up`,`Working with your shoulders or rocking your torso to start`,`Dropping the weight quickly on the way down`,`Bending your wrists back instead of keeping them straight`],breathing:`Breathe out as you curl the handles up and in as you lower under control.`},"cable-pushdown":{cues:[`Fix your elbows at your sides`,`Control the movement`,`Do not let your elbows wander`,`Squeeze your triceps at the bottom`],mistakes:[`Using too much weight`,`Letting your elbows flare out`,`Leaning over the bar`],breathing:`Breathe out as you push down and in as you return upward.`},"db-overhead-ext":{cues:[`Elbows point up`,`Keep your upper arms close to your head`,`Move only at the elbow`,`Keep your ribs firmly down`],mistakes:[`Flaring your elbows wide to the sides.`,`Arching your lower back as the weight goes overhead.`,`Letting your upper arms drift back and forth during the rep.`,`Letting the dumbbell sink uncontrolled too far behind your head.`],breathing:`Breathe in as you lower the dumbbell behind your head and out as you extend your elbows overhead.`},"dips-tri":{cues:[`Keep your elbows close to your body`,`Lower slowly`,`Press through your palms`,`Do not shrug your shoulders`],mistakes:[`Letting your shoulders roll forward`,`Sinking too deep`,`Flaring your elbows out`],breathing:`Breathe in as you lower and out as you press up.`},"bench-dip":{cues:[`Keep your elbows close to your body`,`Lower slowly and under control`,`Keep your chest upright`,`Do not shrug your shoulders`],mistakes:[`Flaring your elbows out`,`Pulling your shoulders up`,`Sinking your hips too deep`],breathing:`Breathe in as you lower and out as you press up.`},"diamond-pushup":{cues:[`Elbows close to your body`,`Keep your hands under your chest`,`Keep your body straight`,`Squeeze your triceps at the top`],mistakes:[`Flaring your elbows`,`Letting your hips sag`,`Hands too far apart`],breathing:`Breathe in as you lower and out as you press up.`},"front-squat":{cues:[`Elbows high`,`Torso upright`,`Heels on the floor`,`Guide your knees over your toes`],mistakes:[`Letting your elbows drop`,`Rounding your back`,`Heels lift off the floor`],breathing:`Breathe in as you lower and out as you stand up.`},"leg-press-calf":{cues:[`Press through the balls of your feet`,`Raise your heels as high as possible`,`Control the heel lowering`,`Keep your knees slightly bent`],mistakes:[`Bending and straightening your knees instead of moving only at the ankle`,`Placing your whole foot flat on the platform so your heels cannot sink`,`Bouncing at the bottom instead of lowering under control`,`Turning your toes strongly inward or outward during the rep`],breathing:`Breathe in as you lower your heels and out as you press up through the balls of your feet.`},"leg-ext":{cues:[`Align your knees with the pivot axis`,`Lift with your quads`,`Keep your hips on the seat`,`Lower under control`],mistakes:[`Your knees sit too far in front of or behind the machine's pivot axis.`,`Swinging the weight up with momentum.`,`Hard-locking your knees at the top.`,`Lifting your hips or lower back off the seat.`],breathing:`Breathe out as you extend your knees and in as you lower the pad.`},"lying-leg-curl":{cues:[`Keep your hips pressed down`,`Curl with your hamstrings`,`Stay slow on the way down`,`Keep your knees in line`],mistakes:[`Lifting your hips off the pad at the top`,`Swinging the pad up with momentum`,`Stopping too early and not lowering the pad fully`,`Turning your feet strongly inward or outward during the curl`],breathing:`Breathe out as you curl the pad up and in as you lower under control.`},"hip-abduction":{cues:[`Sit upright`,`Press your knees outward`,`Control the way back`,`Keep your hips on the seat`],mistakes:[`Leaning your torso forward or rocking back to move the weight.`,`Letting your legs snap together on the return.`,`Lifting your hips off the seat at the widest point.`,`Turning your feet excessively to make the movement easier.`],breathing:`Breathe out as you press your knees outward and in as you return to the start position.`},"standing-calf":{cues:[`Press through your big toe`,`Raise your heels straight up`,`Use the full range of motion at the ankle`,`Control the lowering`],mistakes:[`Bouncing at the bottom instead of lowering under control.`,`Bending your knees noticeably as you lift.`,`Tipping your ankles inward or outward as you raise your heels.`,`Using too short a range of motion and stopping before your heels sink fully.`],breathing:`Breathe in as you lower your heels and out as you press up onto the balls of your feet.`},"db-calf-raise":{cues:[`Rise straight up`,`Press through your big toe`,`Control the lowering`,`Keep your torso upright`],mistakes:[`Bouncing at the bottom instead of lowering under control`,`Tipping your ankles outward or inward`,`Bending your knees and turning the exercise into a squat`,`Leaning your torso forward as you raise your heels`],breathing:`Breathe in as you lower your heels and out as you press up onto your toes.`},"hanging-leg-raise":{cues:[`Do not swing`,`Lift with your core, not with momentum`,`Keep your legs straight`,`Lower your legs under control`],mistakes:[`Swinging your body`,`Using momentum`,`Bending your knees or arching your lower back`],breathing:`Breathe out as you raise your legs and in as you lower.`},"bicycle-crunch":{cues:[`Keep your elbows wide open`,`Rotate from your torso`,`Do not pull on your neck`,`Control every rep`],mistakes:[`Pulling on your neck`,`Working with momentum instead of your abs`,`Letting your hips sag`],breathing:`Breathe out during the twist and in as you return to the middle.`},"c-treadmill":{cues:[`Keep an upright posture`,`Land softly`,`Do not take overly long strides`,`Use your arm swing for balance`],mistakes:[`Holding on to the handrails too long`,`Running hunched over`,`Taking overly long strides`,`Staring at the floor`],breathing:`Breathe in through your nose and out through your mouth, in rhythm with your steps.`},"c-run":{cues:[`Chest up`,`Relax your shoulders`,`Lean slightly forward from the ankles`,`Let your arms swing loosely`],mistakes:[`Taking overly long strides`,`Shrugging your shoulders`,`Landing hard on your heel`],breathing:`Breathe out evenly at push-off and in during the recovery phase.`},"dumbbell-incline-fly":{cues:[`Soft elbows, fixed angle`,`Open wide, but not too deep`,`Squeeze your chest at the top`,`Keep your shoulders down`],mistakes:[`Bending and straightening your elbows like in a press`,`Lowering the dumbbells far below chest height`,`Letting the dumbbells drift behind your shoulders`,`Clanking the dumbbells together at the top`],breathing:`Breathe in as you lower the dumbbells out to the sides and out as you bring them together over your chest.`,steps:[`Set an incline bench and sit down with a dumbbell on each thigh.`,`Lie back and press the dumbbells over your upper chest with your palms facing each other.`,`Bend your elbows slightly and keep that angle.`,`Lower the dumbbells out to the sides in a wide arc until they reach chest height or you feel a slight stretch in your chest.`,`Squeeze your chest and bring the dumbbells together over your upper chest along the same arc.`]},"cable-lying-fly-flat-bench-cable-fly":{cues:[`Keep your elbows slightly bent`,`Keep your arms wide open`,`Control both directions`,`Do not overstretch`],mistakes:[`Locking out your elbows`,`Letting the cables snap back`,`Using too much weight`],breathing:`Breathe out as you bring your hands together and in as you return.`,steps:[`Place a flat bench between two cable stations and attach the handles.`,`Lie back and grab the handles with straight arms.`,`Bring the handles together over your chest with slightly bent elbows.`,`Squeeze your chest at the top.`,`Slowly and under control, return the handles to the start position.`]},"dumbbell-seated-lateral-raise":{cues:[`Lead with your elbows`,`Keep your shoulders down`,`Raise up to shoulder height`,`Control the lowering`],mistakes:[`Swinging your torso to start the movement`,`Shrugging your shoulders toward your ears`,`Raising the dumbbells higher than shoulder height`,`Locking out your elbows and stiffening your arm`],breathing:`Breathe out as you raise the dumbbells to the sides and in as you lower.`,steps:[`Sit upright on a bench, feet flat on the floor, a dumbbell in each hand at your sides.`,`Pull your shoulders down and keep your elbows slightly bent.`,`Raise both arms out to the sides until the dumbbells reach about shoulder height.`,`Pause briefly at the top without shrugging your shoulders.`,`Lower the dumbbells under control back to your sides and repeat.`]},"dumbbell-seated-front-raise":{cues:[`Raise up to shoulder height`,`Keep your torso still`,`Elbows slightly bent`,`Shoulders down and back`],mistakes:[`Leaning your torso back to swing the dumbbells up`,`Raising the dumbbells above shoulder height`,`Shrugging your shoulders toward your ears`,`Dropping the weights quickly on the way down`],breathing:`Breathe out as you raise the dumbbells and in as you lower under control.`,steps:[`Sit upright on a bench, feet flat on the floor, a dumbbell in each hand at your sides.`,`Hold the dumbbells with palms facing down or slightly toward each other and brace your core.`,`Raise both arms, kept straight, forward until the dumbbells reach shoulder height.`,`Pause briefly at the top without leaning back or shrugging your shoulders.`,`Lower the dumbbells under control back to your thighs and repeat with the same posture.`]},"cable-rear-delt":{cues:[`Lead with your elbows`,`Keep your elbows slightly bent`,`Chest up, back straight`,`Do not shrug your shoulders`],mistakes:[`Standing fully upright so it turns into a row`,`Bending and straightening your elbows during the rep`,`Shrugging your shoulders toward your ears`,`Swinging your torso to move the handles`],breathing:`Breathe in as you return the handles to the start position and out as you pull your arms outward and back.`},"cable-seated-row-wide-grip":{cues:[`Keep your elbows high`,`Squeeze your shoulder blades together`,`Keep your back neutral`,`Do not rock your torso`],mistakes:[`Leaning back too far`,`Letting your elbows drop`,`Rounding your back`],breathing:`Breathe out as you pull and in as you extend your arms.`,steps:[`Sit down and brace your feet against the platform.`,`Grab the wide handle with both hands.`,`Keep your torso upright, your arms are extended.`,`Pull the handle to your upper belly while squeezing your upper back together.`,`Slowly and under control, release back to the start position.`]},"cable-bar-lateral-pulldown-reverse-grip":{cues:[`Pull your elbows down`,`Chest up`,`Do not swing your torso`,`Grip the bar firmly`],mistakes:[`Using too much momentum`,`Rounding your shoulders forward`,`Leaning back too far`],breathing:`Breathe out as you pull down and in as you return upward.`,steps:[`Attach the lat pulldown bar and sit with your knees firmly under the pad.`,`Grip the bar underhand (palms facing you) at shoulder width.`,`Lean back slightly, chest up, arms fully extended.`,`Pull the bar to your upper chest with your lats.`,`Slowly and under control, return the bar to the start position.`]},"chin-ups-narrow-parallel-grip":{cues:[`Pull your elbows toward your ribs`,`Lift your chest toward the handles`,`Keep your shoulders down`,`Lower under control`],mistakes:[`Shrugging your shoulders toward your ears as you pull.`,`Swinging or kipping with your legs to get up.`,`Stopping too early so your chin stays below your hands.`,`Dropping down uncontrolled.`],breathing:`Breathe in at the bottom before pulling, out as you pull up, and in again as you lower under control.`,steps:[`Grab the parallel handles close together in a neutral grip and hang with straight arms.`,`Cross your ankles or keep your legs still, brace your core and pull your shoulders down away from your ears.`,`Pull your elbows down and back so your chest rises toward your hands.`,`Keep pulling until your chin is above your hands or the handles.`,`Lower yourself under control until your arms are straight again.`,`Pause briefly at the bottom without relaxing your shoulders and repeat.`]},"dumbbell-incline-shrug":{cues:[`Arms stay long`,`Shrug straight up`,`Keep your chest on the pad`,`Lower under control`],mistakes:[`Bending your elbows and turning the rep into a row`,`Rolling your shoulders forward or back at the top`,`Lifting your chest off the bench to move the weight`,`Using momentum and letting your shoulders drop quickly between reps`],breathing:`Breathe in at the bottom, out as you shrug your shoulders up, and in again as you lower.`,steps:[`Set an incline bench to about 45 degrees and sit with your chest leaning against the pad.`,`Pick up a dumbbell in each hand and let your arms hang straight at your sides with your palms facing in.`,`Plant your feet firmly on the floor and keep your chest on the bench.`,`Shrug your shoulders straight up toward your ears without bending your elbows.`,`Hold briefly at the top, then lower your shoulders under control.`,`Start each rep from fully hanging arms.`]},"dumbbell-incline-hammer-curl":{cues:[`Palms face each other`,`Keep your elbows fixed`,`Lift, do not swing`,`Lower under control`],mistakes:[`Swinging the dumbbells up with your torso`,`Letting your elbows drift forward during the curl`,`Rotating your palms upward at the top`,`Cutting the lowering phase short`],breathing:`Breathe out as you curl the dumbbells up and in as you lower.`,steps:[`Set an incline bench and lean back with a dumbbell in each hand.`,`Let your arms hang straight at your sides, palms facing each other.`,`Keep your upper arms still and curl both dumbbells toward your shoulders.`,`Stop when your forearms are almost vertical and squeeze your biceps.`,`Lower the dumbbells slowly until your elbows are fully extended again.`,`Repeat without swinging your torso or letting your shoulders roll forward.`]},"dumbbell-prone-incline-curl":{cues:[`Keep your chest on the bench`,`Your elbows stay still`,`Curl through the full range of motion`,`Lower under control`],mistakes:[`Lifting your chest off the bench to swing the weights`,`Letting your elbows drift forward during the curl`,`Cutting the rep short and not lowering the dumbbells fully`,`Bending your wrists back instead of keeping them neutral`],breathing:`Breathe in as you lower the dumbbells and out as you curl up.`,steps:[`Set an incline bench to about 45 degrees and lie face down on it with your chest supported.`,`Hold a dumbbell in each hand, arms hanging straight down, palms facing forward.`,`Keep your upper arms still and curl both dumbbells toward your shoulders.`,`Pause briefly at the top and squeeze your biceps.`,`Lower the dumbbells slowly until your arms are fully extended again.`]},"dumbbell-one-arm-triceps-extension":{cues:[`Keep your upper arm vertical`,`Move only your forearm`,`Do not swing`,`Fully extend your elbow`],mistakes:[`Moving your upper arm along with it`,`Lowering the weight too deep`,`Letting your elbow flare outward`,`Rushing the movement`],breathing:`Breathe in as you lower the dumbbell and out as you press up.`,steps:[`Hold a dumbbell in one hand, your arm extended overhead.`,`Support your upper arm with your free hand if needed.`,`Lower the dumbbell behind your head by bending your elbow.`,`Pause briefly when your forearm is horizontal.`,`Fully extend your arm to return to the start position.`]},"lever-seated-dips":{cues:[`Keep your elbows close to your body`,`Control the lowering`,`Do not hyperextend your elbows`,`Sit upright`],mistakes:[`Flaring your elbows out`,`Using too much weight`,`Working with jerks or momentum`],breathing:`Breathe out as you push down and in as you return upward.`,steps:[`Adjust the seat and choose a suitable weight.`,`Sit down and grip the handles firmly.`,`Push the handles down until your arms are fully extended.`,`Pause briefly at the top.`,`Slowly return the handles to the start position.`]},"dumbbell-squat":{cues:[`Chest up`,`Guide your knees over your toes`,`Keep your heels on the floor`,`Stand fully tall at the top`],mistakes:[`Letting your knees fall inward as you lower or stand up.`,`Coming up onto your toes and lifting your heels off the floor.`,`Rounding your upper or lower back at the bottom.`,`Tipping your torso forward so the dumbbells swing ahead of your legs.`],breathing:`Breathe in as you lower into the squat and out as you stand up.`,steps:[`Stand upright with a dumbbell in each hand at your sides, feet about shoulder-width apart.`,`Brace your core, keep your chest up and your arms straight.`,`Bend hips and knees together and sit down and slightly back.`,`Go deep enough that your thighs are at least parallel to the floor, or as deep as you can keep your heels down.`,`Press back up through your midfoot and heels.`,`Stand tall at the top with hips and knees extended before starting the next rep.`]},squat:{cues:[`Guide your knees over your toes`,`Keep a neutral spine`,`Weight on midfoot and heels`,`Chest up`],mistakes:[`Letting your knees cave inward`,`Rounding your lower back`,`Not lowering to parallel depth`],breathing:`Breathe in as you lower and out as you stand up.`,steps:[`Stand shoulder-width apart, toes turned out slightly.`,`Brace your core and keep your chest up.`,`Push your hips back first and then bend your knees.`,`Go down until your thighs are at least parallel to the floor.`,`Press up through your heels back to standing.`]},"barbell-lunge":{cues:[`Stay upright`,`Front heel on the floor`,`Guide your knees over your toes`,`Control the lowering`],mistakes:[`Taking steps so short that the front knee shoots far past your toes.`,`Leaning your torso forward as you lower.`,`Letting your front knee cave inward.`,`Pushing off the back foot instead of driving through the front foot.`],breathing:`Breathe in as you step forward and lower, and out as you press up to standing.`,steps:[`Place the barbell on your upper back and stand upright, feet hip-width apart.`,`Brace your core and take a controlled step forward.`,`Lower your body until both knees are bent and your back knee sinks toward the floor.`,`At the bottom, keep your front foot flat and your torso upright.`,`Press up through your front foot and bring your feet together.`,`Repeat with the other leg and alternate on every rep.`]},"single-leg-rdl":{cues:[`Hips back`,`Straight back`,`Feel the stretch in your hamstrings`,`Do not round`],mistakes:[`Rounding your back`,`Bending your knee too much`,`Bouncing at the bottom`],breathing:`Breathe in as you lower and out as you stand up.`},"lever-standing-hip-extension":{cues:[`Press through your heel`,`Keep your knee slightly bent`,`Do not arch your lower back`,`Hold briefly at the top`],mistakes:[`Arching your lower back too much`,`Using momentum`,`Locking out your knee`,`Not completing the extension`],breathing:`Breathe out as you extend your hip and in as you return.`,steps:[`Adjust the machine to your body height.`,`Place one foot on the platform and lean your chest against the pad.`,`Brace your core and hold on to the handles for stability.`,`Extend your hip and push the lever back with your heel.`,`Return to the start position and repeat.`]},"band-hip-adduction":{cues:[`Keep your core braced`,`Move under control`,`Do not swing`,`Keep an upright posture`],mistakes:[`Using momentum`,`Rotating your hip outward`,`Bending your standing leg too much`],breathing:`Breathe out as you pull your leg in and in as you return.`,steps:[`Anchor a resistance band at ankle height to a stable anchor.`,`Loop the other end around the ankle of your working leg.`,`Stand upright and hold on to a support if needed.`,`Move your working leg inward across your body from the hip.`,`Slowly return to the start position and repeat.`]},"sit-ups":{cues:[`Do not pull on your neck`,`Lift your chest first`,`Keep your abs tensed throughout`,`Control the lowering`],mistakes:[`Yanking on your neck`,`Using momentum`,`Lifting your feet off the floor`],breathing:`Breathe out as you sit up and in as you lower.`,steps:[`Lie flat on your back, knees bent, feet secured.`,`Place your hands behind your head or crossed over your chest.`,`Brace your core and sit your torso up to a seated position.`,`Pause briefly at the top and slowly lie back down.`,`Repeat for the desired number of reps.`]},"vertical-leg-raise-on-parallel-bars":{cues:[`Keep your legs straight`,`Brace and stop the swinging`,`Raise under control`,`Keep your shoulders down`],mistakes:[`Swinging your torso to start each rep`,`Bending your knees as you raise your legs`,`Shrugging your shoulders toward your ears`,`Dropping your legs quickly as you lower`],breathing:`Breathe out as you raise your legs and in as you lower to the start position.`,steps:[`Support yourself on the parallel bars with straight arms, your legs hanging together.`,`Pull your shoulders down and brace your core so your body does not swing.`,`Keep your knees straight and raise your legs forward.`,`Raise them until they reach hip height or a little above.`,`Pause briefly at the top without leaning back.`,`Lower your legs under control to the start position and settle before starting the next rep.`]},"crunch-on-bench":{cues:[`Lift with your abs`,`Keep your chin slightly tucked`,`Do not arch your lower back`,`Control the movement`],mistakes:[`Pulling on your neck`,`Rushing the reps`,`Sitting up too high`],breathing:`Breathe out as you sit up and in as you lower.`,steps:[`Lie flat on a bench, knees bent, feet secured or flat.`,`Cross your arms over your chest or place your hands behind your head.`,`Brace your core and raise your shoulders toward your knees.`,`Squeeze at the top and hold briefly.`,`Lower your torso under control back onto the bench.`]}},r={...e,...t,...n};export{r as TIPS_EN};